    /// Lift 0F 38-prefixed (three-byte) opcodes
    fn lift_0f38_opcode(
        &self,
        bytes: &[u8],
        prefix: &X86Prefix,
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if bytes.is_empty() {
            return Err(LiftError::Incomplete {
                addr: pc,
                have: prefix.cursor + 1,
                need: prefix.cursor + 2,
            });
        }

        let opcode3 = bytes[0];
        let after_opcode = &bytes[1..];
        let prefix3 = X86Prefix {
            cursor: prefix.cursor + 1,
            ..prefix.clone()
        };

        match opcode3 {
            0x00 => self.lift_sse_pshufb(after_opcode, &prefix3, pc, ctx),
            0x01..=0x03 | 0x05..=0x07 => {
                self.lift_sse_horizontal_integer(opcode3, after_opcode, &prefix3, pc, ctx)
            }
            0x04 => self.lift_sse_pmaddubsw(after_opcode, &prefix3, pc, ctx),
            0x08..=0x0A => self.lift_sse_psign(opcode3, after_opcode, &prefix3, pc, ctx),
            0x0B => self.lift_sse_pmulhrsw(after_opcode, &prefix3, pc, ctx),
            0x10 | 0x14 | 0x15 => {
                self.lift_sse_variable_blend(opcode3, after_opcode, &prefix3, pc, ctx)
            }
            0x17 => self.lift_sse_ptest(after_opcode, &prefix3, pc, ctx),
            0x1C..=0x1E => self.lift_sse_pabs(opcode3, after_opcode, &prefix3, pc, ctx),
            0x20..=0x25 | 0x30..=0x35 => {
                self.lift_sse_packed_extend(opcode3, after_opcode, &prefix3, pc, ctx)
            }
            0x28 => self.lift_sse_pmuldq(after_opcode, &prefix3, true, pc, ctx),
            0x2A => self.lift_sse_movntdqa(after_opcode, &prefix3, pc, ctx),
            0x2B => self.lift_sse_integer_pack(opcode3, after_opcode, &prefix3, pc, ctx),
            0x29 | 0x37 => self.lift_sse_integer_compare(opcode3, after_opcode, &prefix3, pc, ctx),
            0x38..=0x3F => self.lift_sse_packed_minmax(opcode3, after_opcode, &prefix3, pc, ctx),
            0x40 => self.lift_sse_pmulld(after_opcode, &prefix3, pc, ctx),
            0x41 => self.lift_sse_phminposuw(after_opcode, &prefix3, pc, ctx),
            0xDB..=0xDF => self.lift_sse_aes_round(opcode3, after_opcode, &prefix3, pc, ctx),
            0x8A | 0x8B => self.lift_movrs_0f38(opcode3, after_opcode, &prefix3, pc, ctx),
            0xF6 => self.lift_adx_0f38(after_opcode, &prefix3, pc, ctx),
            0xF0 | 0xF1 if prefix3.rep_prefix == Some(0xF2) => {
                self.lift_crc32_0f38(opcode3, after_opcode, &prefix3, pc, ctx)
            }
            0xF0 | 0xF1 => self.lift_movbe_0f38(opcode3, after_opcode, &prefix3, pc, ctx),
            0xFC => self.lift_rao_int_0f38(after_opcode, &prefix3, pc, ctx),
            _ => {
                if self.strict {
                    Err(LiftError::Unsupported {
                        addr: pc,
                        mnemonic: format!("0x0F 0x38 0x{:02X}", opcode3),
                    })
                } else {
                    Ok(LiftResult::fallthrough(
                        vec![SmirOp::new(OpId(0), pc, OpKind::Nop)],
                        prefix3.cursor,
                    ))
                }
            }
        }
    }

    /// Expand MASKMOVDQU/VMASKMOVDQU into sixteen independently predicated
    /// byte stores. The predicate for byte `n` is bit 7 of mask byte `n`.
    /// A false predicate performs no memory access, matching the instruction's
    /// byte-selective store semantics and its permitted all-zero-mask behavior.
    fn append_maskmovdqu(
        &self,
        data: VReg,
        mask: VReg,
        address_size_override: bool,
        segment_override: Option<u8>,
        pc: u64,
        ctx: &mut LiftContext,
        ops: &mut Vec<SmirOp>,
    ) {
        let base = if address_size_override {
            let truncated = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::And {
                    dst: truncated,
                    src1: self.gpr(7),
                    src2: SrcOperand::Imm(0xFFFF_FFFF),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            truncated
        } else {
            self.gpr(7)
        };

        for lane in 0..16u8 {
            let mask_byte = ctx.alloc_vreg();
            let active = ctx.alloc_vreg();
            let data_byte = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: mask_byte,
                    vec: mask,
                    lane,
                    elem: VecElementType::I8,
                    sign: SignExtend::Zero,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Shr {
                    dst: active,
                    src: mask_byte,
                    amount: SrcOperand::Imm(7),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: data_byte,
                    vec: data,
                    lane,
                    elem: VecElementType::I8,
                    sign: SignExtend::Zero,
                },
            ));
            let disp = i64::from(lane);
            let addr = match segment_override {
                Some(0x64) => Address::SegmentRel {
                    segment: VReg::Arch(ArchReg::X86(X86Reg::FsBase)),
                    base: Some(base),
                    index: None,
                    scale: 1,
                    disp,
                },
                Some(0x65) => Address::SegmentRel {
                    segment: VReg::Arch(ArchReg::X86(X86Reg::GsBase)),
                    base: Some(base),
                    index: None,
                    scale: 1,
                    disp,
                },
                _ => Address::base_off(base, disp),
            };
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::PredStore {
                    src: SrcOperand::Reg(data_byte),
                    cond: active,
                    addr,
                    width: MemWidth::B1,
                },
            ));
        }
    }

    fn lift_sse_maskmovdqu(
        &self,
        bytes: &[u8],
        prefix: &X86Prefix,
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if !prefix.operand_size_override {
            return Err(LiftError::Unsupported {
                addr: pc,
                mnemonic: "MMX MASKMOVQ".to_string(),
            });
        }
        if prefix.rep_prefix.is_some() || prefix.lock || prefix.rex2.is_some() {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let modrm = decode_modrm(bytes, prefix, pc)?;
        if modrm.is_memory {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes[..modrm.bytes_consumed.min(bytes.len())].to_vec(),
            });
        }
        let mut ops = Vec::new();
        self.append_maskmovdqu(
            self.xmm(modrm.reg),
            self.xmm(modrm.rm),
            prefix.address_size_override,
            prefix.segment_override,
            pc,
            ctx,
            &mut ops,
        );
        Ok(LiftResult::fallthrough(
            ops,
            prefix.cursor + modrm.bytes_consumed,
        ))
    }

    fn lift_vex_maskmovdqu(
        &self,
        prefix: VecPrefix,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Vex
            || prefix.map != X86VecMap::Map0F
            || prefix.pp != X86SsePrefix::OpSize
            || prefix.l_bits != 0
            || prefix.vvvv != 0
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        if modrm.is_memory {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let mut ops = Vec::new();
        self.append_maskmovdqu(
            self.xmm(modrm.reg),
            self.xmm(modrm.rm),
            prefix.address_size_override,
            prefix.segment_override,
            pc,
            ctx,
            &mut ops,
        );
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn lift_vex_masked_memory(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Vex
            || prefix.map != X86VecMap::Map0F38
            || prefix.pp != X86SsePrefix::OpSize
            || (matches!(opcode, 0x2C..=0x2F) && prefix.w)
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let load = matches!(opcode, 0x2C | 0x2D | 0x8C);
        let elem = match opcode {
            0x2C | 0x2E => VecElementType::F32,
            0x2D | 0x2F => VecElementType::F64,
            0x8C | 0x8E if prefix.w => VecElementType::I64,
            0x8C | 0x8E => VecElementType::I32,
            _ => unreachable!(),
        };
        let mem_width = if elem.bytes() == 4 {
            MemWidth::B4
        } else {
            MemWidth::B8
        };
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            address_size_override: prefix.address_size_override,
            segment_override: prefix.segment_override,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        if !modrm.is_memory {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let next_pc = pc + cursor as u64 + modrm.bytes_consumed as u64;
        let (addr, mut ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
        let base = ctx.alloc_vreg();
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::Lea { dst: base, addr },
        ));
        let mask = self.vec_reg(prefix.vvvv, prefix.width);
        let lanes = prefix.width.lanes(elem) as u8;
        let mut active = Vec::with_capacity(lanes as usize);
        for lane in 0..lanes {
            let mask_lane = ctx.alloc_vreg();
            let condition = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: mask_lane,
                    vec: mask,
                    lane,
                    elem,
                    sign: SignExtend::Zero,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Shr {
                    dst: condition,
                    src: mask_lane,
                    amount: SrcOperand::Imm(i64::from(elem.bytes() * 8 - 1)),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            active.push(condition);
        }

        if load {
            let dst = self.vec_reg(modrm.reg, prefix.width);
            let loaded = self.append_zero_vector(prefix.width, elem, pc, ctx, &mut ops);
            for (lane, condition) in active.into_iter().enumerate() {
                let scalar = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Mov {
                        dst: scalar,
                        src: SrcOperand::Imm(0),
                        width: OpWidth::W64,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::PredLoad {
                        dst: scalar,
                        cond: condition,
                        addr: Address::base_off(base, lane as i64 * i64::from(elem.bytes())),
                        width: mem_width,
                        signed: SignExtend::Zero,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VInsertLane {
                        dst: loaded,
                        vec: loaded,
                        scalar,
                        lane: lane as u8,
                        elem,
                    },
                ));
            }
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VMov {
                    dst,
                    src: loaded,
                    width: prefix.width,
                },
            ));
        } else {
            let data = self.vec_reg(modrm.reg, prefix.width);
            let mut values = Vec::with_capacity(lanes as usize);
            for lane in 0..lanes {
                let scalar = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VExtractLane {
                        dst: scalar,
                        vec: data,
                        lane,
                        elem,
                        sign: SignExtend::Zero,
                    },
                ));
                values.push(scalar);
            }
            for (lane, (condition, scalar)) in active.into_iter().zip(values).enumerate() {
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::PredStore {
                        src: SrcOperand::Reg(scalar),
                        cond: condition,
                        addr: Address::base_off(base, lane as i64 * i64::from(elem.bytes())),
                        width: mem_width,
                    },
                ));
            }
        }
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn append_vsib_lane_address(
        &self,
        x86_addr: &X86Address,
        index: VReg,
        lane: u8,
        index_elem: VecElementType,
        pc: u64,
        ctx: &mut LiftContext,
        ops: &mut Vec<SmirOp>,
    ) -> Address {
        let width = x86_addr.address_width;
        let mut offset = ctx.alloc_vreg();
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::VExtractLane {
                dst: offset,
                vec: index,
                lane,
                elem: index_elem,
                sign: SignExtend::Sign,
            },
        ));
        if x86_addr.scale != 1 {
            let scaled = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Shl {
                    dst: scaled,
                    src: offset,
                    amount: SrcOperand::Imm(i64::from(x86_addr.scale.trailing_zeros())),
                    width,
                    flags: FlagUpdate::None,
                },
            ));
            offset = scaled;
        }
        if let Some(base) = x86_addr.base {
            let sum = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Add {
                    dst: sum,
                    src1: self.gpr(base),
                    src2: SrcOperand::Reg(offset),
                    width,
                    flags: FlagUpdate::None,
                },
            ));
            offset = sum;
        }
        if x86_addr.disp != 0 {
            let sum = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Add {
                    dst: sum,
                    src1: offset,
                    src2: SrcOperand::Imm(x86_addr.disp),
                    width,
                    flags: FlagUpdate::None,
                },
            ));
            offset = sum;
        }
        match x86_addr.segment {
            Some(segment) => Address::SegmentRel {
                segment: VReg::Arch(ArchReg::X86(segment)),
                base: Some(offset),
                index: None,
                scale: 1,
                disp: 0,
            },
            None => Address::Direct(offset),
        }
    }

    fn lift_vec_gather(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.map != X86VecMap::Map0F38
            || prefix.pp != X86SsePrefix::OpSize
            || prefix.b
            || prefix.zeroing
            || prefix.l_bits == 3
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        if prefix.encoding == VecEncodingKind::Evex && (prefix.aaa == 0 || prefix.vvvv != 0) {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }

        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            address_size_override: prefix.address_size_override,
            segment_override: prefix.segment_override,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        if !modrm.is_memory || modrm.byte & 7 != 4 || bytes.len() <= cursor + 1 {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }

        let sib = bytes[cursor + 1];
        let index_number = ((sib >> 3) & 7)
            | modrm_prefix.rex_x()
            | if prefix.encoding == VecEncodingKind::Evex && prefix.v_high {
                16
            } else {
                0
            };
        let dst_number = modrm.reg
            + if prefix.encoding == VecEncodingKind::Evex && prefix.reg_high {
                16
            } else {
                0
            };
        if dst_number == index_number
            || (prefix.encoding == VecEncodingKind::Vex
                && (prefix.vvvv == dst_number || prefix.vvvv == index_number))
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }

        let data_elem = if prefix.w {
            VecElementType::I64
        } else {
            VecElementType::I32
        };
        let index_elem = if opcode & 1 == 0 {
            VecElementType::I32
        } else {
            VecElementType::I64
        };
        let lanes = prefix
            .width
            .lanes(data_elem)
            .min(prefix.width.lanes(index_elem)) as u8;
        let result_bits = usize::from(lanes) * data_elem.bytes() as usize * 8;
        let result_width = match result_bits {
            64 => VecWidth::V64,
            128 => VecWidth::V128,
            256 => VecWidth::V256,
            512 => VecWidth::V512,
            _ => unreachable!("invalid gather result width"),
        };
        let index_bits = usize::from(lanes) * index_elem.bytes() as usize * 8;
        let index_width = match index_bits {
            64 => VecWidth::V64,
            128 => VecWidth::V128,
            256 => VecWidth::V256,
            512 => VecWidth::V512,
            _ => unreachable!("invalid gather index width"),
        };
        let dst = self.vec_reg(dst_number, result_width);
        let index = self.vec_reg(index_number, index_width);
        let old_dst = ctx.alloc_vreg();
        let mut ops = vec![SmirOp::new(
            OpId(0),
            pc,
            OpKind::VMov {
                dst: old_dst,
                src: dst,
                width: result_width,
            },
        )];

        // Normalize destination width before the first potentially faulting
        // access. Intel permits unused high portions to be cleared even when
        // the instruction suspends before gathering its first element.
        let initial_dst = self.append_zero_vector(result_width, data_elem, pc, ctx, &mut ops);
        for lane in 0..lanes {
            let old = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: old,
                    vec: old_dst,
                    lane,
                    elem: data_elem,
                    sign: SignExtend::Zero,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VInsertLane {
                    dst: initial_dst,
                    vec: initial_dst,
                    scalar: old,
                    lane,
                    elem: data_elem,
                },
            ));
        }
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::VMov {
                dst,
                src: initial_dst,
                width: result_width,
            },
        ));

        let scalar_zero = ctx.alloc_vreg();
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::Mov {
                dst: scalar_zero,
                src: SrcOperand::Imm(0),
                width: OpWidth::W64,
            },
        ));
        let mut conditions = Vec::with_capacity(lanes as usize);
        let vector_mask = if prefix.encoding == VecEncodingKind::Vex {
            let mask = self.vec_reg(prefix.vvvv, result_width);
            let old_mask = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VMov {
                    dst: old_mask,
                    src: mask,
                    width: result_width,
                },
            ));
            let normalized = self.append_zero_vector(result_width, data_elem, pc, ctx, &mut ops);
            for lane in 0..lanes {
                let raw = ctx.alloc_vreg();
                let cond = ctx.alloc_vreg();
                let sign_mask = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VExtractLane {
                        dst: raw,
                        vec: old_mask,
                        lane,
                        elem: data_elem,
                        sign: SignExtend::Zero,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Shr {
                        dst: cond,
                        src: raw,
                        amount: SrcOperand::Imm(i64::from(data_elem.bytes() * 8 - 1)),
                        width: if data_elem == VecElementType::I32 {
                            OpWidth::W32
                        } else {
                            OpWidth::W64
                        },
                        flags: FlagUpdate::None,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Sub {
                        dst: sign_mask,
                        src1: scalar_zero,
                        src2: SrcOperand::Reg(cond),
                        width: if data_elem == VecElementType::I32 {
                            OpWidth::W32
                        } else {
                            OpWidth::W64
                        },
                        flags: FlagUpdate::None,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VInsertLane {
                        dst: normalized,
                        vec: normalized,
                        scalar: sign_mask,
                        lane,
                        elem: data_elem,
                    },
                ));
                conditions.push(cond);
            }
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VMov {
                    dst: mask,
                    src: normalized,
                    width: result_width,
                },
            ));
            Some(mask)
        } else {
            let mask = VReg::Arch(ArchReg::X86(X86Reg::K(prefix.aaa)));
            let snapshot = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Mov {
                    dst: snapshot,
                    src: SrcOperand::Reg(mask),
                    width: OpWidth::W64,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::And {
                    dst: mask,
                    src1: mask,
                    src2: SrcOperand::Imm(((1u64 << lanes) - 1) as i64),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            for lane in 0..lanes {
                let shifted = ctx.alloc_vreg();
                let cond = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Shr {
                        dst: shifted,
                        src: snapshot,
                        amount: SrcOperand::Imm(i64::from(lane)),
                        width: OpWidth::W64,
                        flags: FlagUpdate::None,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::And {
                        dst: cond,
                        src1: shifted,
                        src2: SrcOperand::Imm(1),
                        width: OpWidth::W64,
                        flags: FlagUpdate::None,
                    },
                ));
                conditions.push(cond);
            }
            None
        };

        let mut x86_addr = modrm.addr.unwrap();
        x86_addr.index = None;
        if prefix.encoding == VecEncodingKind::Evex && x86_addr.disp_size == DispSize::Disp8 {
            x86_addr.disp *= i64::from(data_elem.bytes());
        }
        let mem_width = if data_elem == VecElementType::I32 {
            MemWidth::B4
        } else {
            MemWidth::B8
        };
        for (lane, cond) in conditions.into_iter().enumerate() {
            let lane = lane as u8;
            let value = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: value,
                    vec: dst,
                    lane,
                    elem: data_elem,
                    sign: SignExtend::Zero,
                },
            ));
            let addr = self
                .append_vsib_lane_address(&x86_addr, index, lane, index_elem, pc, ctx, &mut ops);
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::PredLoad {
                    dst: value,
                    cond,
                    addr,
                    width: mem_width,
                    signed: SignExtend::Zero,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VInsertLane {
                    dst,
                    vec: dst,
                    scalar: value,
                    lane,
                    elem: data_elem,
                },
            ));
            if let Some(mask) = vector_mask {
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VInsertLane {
                        dst: mask,
                        vec: mask,
                        scalar: scalar_zero,
                        lane,
                        elem: data_elem,
                    },
                ));
            } else {
                let mask = VReg::Arch(ArchReg::X86(X86Reg::K(prefix.aaa)));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::And {
                        dst: mask,
                        src1: mask,
                        src2: SrcOperand::Imm(!(1i64 << lane)),
                        width: OpWidth::W64,
                        flags: FlagUpdate::None,
                    },
                ));
            }
        }

        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn lift_evex_scatter(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Evex
            || prefix.map != X86VecMap::Map0F38
            || prefix.pp != X86SsePrefix::OpSize
            || prefix.b
            || prefix.zeroing
            || prefix.l_bits == 3
            || prefix.aaa == 0
            || prefix.vvvv != 0
            || !matches!(opcode, 0xA0..=0xA3)
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            address_size_override: prefix.address_size_override,
            segment_override: prefix.segment_override,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        if !modrm.is_memory || modrm.byte & 7 != 4 || bytes.len() <= cursor + 1 {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let sib = bytes[cursor + 1];
        let index_number =
            ((sib >> 3) & 7) | modrm_prefix.rex_x() | if prefix.v_high { 16 } else { 0 };
        let source_number = modrm.reg + if prefix.reg_high { 16 } else { 0 };
        if source_number == index_number {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }

        let data_elem = if prefix.w {
            VecElementType::I64
        } else {
            VecElementType::I32
        };
        let index_elem = if opcode & 1 == 0 {
            VecElementType::I32
        } else {
            VecElementType::I64
        };
        let lanes = prefix
            .width
            .lanes(data_elem)
            .min(prefix.width.lanes(index_elem)) as u8;
        let width_for = |bits: usize| match bits {
            64 => VecWidth::V64,
            128 => VecWidth::V128,
            256 => VecWidth::V256,
            512 => VecWidth::V512,
            _ => unreachable!("invalid scatter vector width"),
        };
        let source_width = width_for(usize::from(lanes) * data_elem.bytes() as usize * 8);
        let index_width = width_for(usize::from(lanes) * index_elem.bytes() as usize * 8);
        let source = self.vec_reg(source_number, source_width);
        let index = self.vec_reg(index_number, index_width);
        let mask = VReg::Arch(ArchReg::X86(X86Reg::K(prefix.aaa)));
        let snapshot = ctx.alloc_vreg();
        let valid_mask = (1u64 << lanes) - 1;
        let mut ops = vec![
            SmirOp::new(
                OpId(0),
                pc,
                OpKind::Mov {
                    dst: snapshot,
                    src: SrcOperand::Reg(mask),
                    width: OpWidth::W64,
                },
            ),
            SmirOp::new(
                OpId(1),
                pc,
                OpKind::And {
                    dst: mask,
                    src1: mask,
                    src2: SrcOperand::Imm(valid_mask as i64),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ),
        ];
        let mut x86_addr = modrm.addr.unwrap();
        x86_addr.index = None;
        if x86_addr.disp_size == DispSize::Disp8 {
            x86_addr.disp *= i64::from(data_elem.bytes());
        }
        let mem_width = if data_elem == VecElementType::I32 {
            MemWidth::B4
        } else {
            MemWidth::B8
        };
        for lane in 0..lanes {
            let shifted = ctx.alloc_vreg();
            let cond = ctx.alloc_vreg();
            let value = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Shr {
                    dst: shifted,
                    src: snapshot,
                    amount: SrcOperand::Imm(i64::from(lane)),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::And {
                    dst: cond,
                    src1: shifted,
                    src2: SrcOperand::Imm(1),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: value,
                    vec: source,
                    lane,
                    elem: data_elem,
                    sign: SignExtend::Zero,
                },
            ));
            let addr = self
                .append_vsib_lane_address(&x86_addr, index, lane, index_elem, pc, ctx, &mut ops);
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::PredStore {
                    src: SrcOperand::Reg(value),
                    cond,
                    addr,
                    width: mem_width,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::And {
                    dst: mask,
                    src1: mask,
                    src2: SrcOperand::Imm(!(1i64 << lane)),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
        }
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn lift_vec_fma3(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.map != X86VecMap::Map0F38 || prefix.pp != X86SsePrefix::OpSize {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let low = opcode & 0x0F;
        let alternating = matches!(low, 0x06 | 0x07);
        let scalar = matches!(low, 0x09 | 0x0B | 0x0D | 0x0F);
        if prefix.encoding == VecEncodingKind::Evex
            && ((prefix.zeroing && prefix.aaa == 0) || (!scalar && prefix.l_bits == 3))
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let elem = if prefix.w {
            VecElementType::F64
        } else {
            VecElementType::F32
        };
        let operation_width = if scalar { VecWidth::V128 } else { prefix.width };
        let lanes = if scalar {
            1
        } else {
            operation_width.lanes(elem) as u8
        };
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            address_size_override: prefix.address_size_override,
            segment_override: prefix.segment_override,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        let next_pc = pc + cursor as u64 + modrm.bytes_consumed as u64;
        let mut ops = Vec::new();
        if prefix.encoding == VecEncodingKind::Evex
            && prefix.b
            && !modrm.is_memory
            && !scalar
            && operation_width != VecWidth::V512
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let dst = self.vec_reg(
            modrm.reg
                + if prefix.encoding == VecEncodingKind::Evex && prefix.reg_high {
                    16
                } else {
                    0
                },
            operation_width,
        );
        let old_dst = dst;
        let vex_src = self.vec_reg(
            prefix.vvvv
                + if prefix.encoding == VecEncodingKind::Evex && prefix.v_high {
                    16
                } else {
                    0
                },
            operation_width,
        );
        let mask_cond = self.append_evex_mask_condition(prefix, pc, ctx, &mut ops);
        let rm_src = if modrm.is_memory {
            let (addr, pre_ops) = if scalar {
                self.vec_scalar_addr_to_smir(
                    prefix,
                    modrm.addr.as_ref().unwrap(),
                    next_pc,
                    elem,
                    ctx,
                )
            } else if prefix.encoding == VecEncodingKind::Evex && prefix.b {
                self.vec_disp8_addr_to_smir(
                    prefix,
                    modrm.addr.as_ref().unwrap(),
                    next_pc,
                    elem.bytes(),
                    ctx,
                )
            } else {
                self.vec_full_addr_to_smir(prefix, modrm.addr.as_ref().unwrap(), next_pc, ctx)
            };
            ops.extend(pre_ops);
            if scalar {
                let scalar_value = ctx.alloc_vreg();
                let mem_width = if elem == VecElementType::F32 {
                    MemWidth::B4
                } else {
                    MemWidth::B8
                };
                if let Some(cond) = mask_cond {
                    ops.push(SmirOp::new(
                        OpId(ops.len() as u16),
                        pc,
                        OpKind::Mov {
                            dst: scalar_value,
                            src: SrcOperand::Imm(0),
                            width: OpWidth::W64,
                        },
                    ));
                    ops.push(SmirOp::new(
                        OpId(ops.len() as u16),
                        pc,
                        OpKind::PredLoad {
                            dst: scalar_value,
                            cond,
                            addr,
                            width: mem_width,
                            signed: SignExtend::Zero,
                        },
                    ));
                } else {
                    ops.push(SmirOp::new(
                        OpId(ops.len() as u16),
                        pc,
                        OpKind::Load {
                            dst: scalar_value,
                            addr,
                            width: mem_width,
                            sign: SignExtend::Zero,
                        },
                    ));
                }
                let vector = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VBroadcast {
                        dst: vector,
                        scalar: scalar_value,
                        elem,
                        lanes: 1,
                    },
                ));
                vector
            } else if prefix.encoding == VecEncodingKind::Evex && prefix.aaa != 0 {
                self.append_evex_masked_vector_source(
                    addr,
                    elem,
                    operation_width,
                    prefix.b,
                    VReg::Arch(ArchReg::X86(X86Reg::K(prefix.aaa))),
                    pc,
                    ctx,
                    &mut ops,
                )
            } else if prefix.encoding == VecEncodingKind::Evex && prefix.b {
                let scalar_value = ctx.alloc_vreg();
                let vector = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Load {
                        dst: scalar_value,
                        addr,
                        width: if elem == VecElementType::F32 {
                            MemWidth::B4
                        } else {
                            MemWidth::B8
                        },
                        sign: SignExtend::Zero,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VBroadcast {
                        dst: vector,
                        scalar: scalar_value,
                        elem,
                        lanes,
                    },
                ));
                vector
            } else {
                let vector = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VLoad {
                        dst: vector,
                        addr,
                        width: operation_width,
                    },
                ));
                vector
            }
        } else {
            self.vec_reg(
                modrm.rm
                    + if prefix.encoding == VecEncodingKind::Evex && prefix.rm_high {
                        16
                    } else {
                        0
                    },
                operation_width,
            )
        };

        let order = opcode >> 4;
        let (mul1, mul2, acc) = match order {
            0x09 => (old_dst, rm_src, vex_src),
            0x0A => (vex_src, old_dst, rm_src),
            0x0B => (vex_src, rm_src, old_dst),
            _ => unreachable!(),
        };
        let negate_product = matches!(low, 0x0C | 0x0D | 0x0E | 0x0F);
        let negate_acc = matches!(low, 0x0A | 0x0B | 0x0E | 0x0F);
        let raw = ctx.alloc_vreg();
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::VFma {
                dst: raw,
                src1: mul1,
                src2: mul2,
                acc,
                elem,
                lanes,
                negate_product,
                negate_acc: if alternating { false } else { negate_acc },
            },
        ));

        let result = if alternating {
            let sub = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VFma {
                    dst: sub,
                    src1: mul1,
                    src2: mul2,
                    acc,
                    elem,
                    lanes,
                    negate_product: false,
                    negate_acc: true,
                },
            ));
            let selected = self.append_zero_vector(operation_width, elem, pc, ctx, &mut ops);
            let subtract_even = low == 0x06;
            for lane in 0..lanes {
                let scalar_value = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VExtractLane {
                        dst: scalar_value,
                        vec: if (lane & 1 == 0) == subtract_even {
                            sub
                        } else {
                            raw
                        },
                        lane,
                        elem,
                        sign: SignExtend::Zero,
                    },
                ));
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VInsertLane {
                        dst: selected,
                        vec: selected,
                        scalar: scalar_value,
                        lane,
                        elem,
                    },
                ));
            }
            selected
        } else {
            raw
        };

        if scalar {
            let low_result = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: low_result,
                    vec: result,
                    lane: 0,
                    elem,
                    sign: SignExtend::Zero,
                },
            ));
            let low_result = self.append_evex_scalar_select(
                prefix, mask_cond, dst, low_result, elem, pc, ctx, &mut ops,
            );
            self.append_vex_scalar_result(dst, old_dst, low_result, elem, pc, ctx, &mut ops);
        } else {
            if prefix.encoding == VecEncodingKind::Evex {
                self.append_evex_vector_mask_result(prefix, dst, result, elem, pc, ctx, &mut ops);
            } else {
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VMov {
                        dst,
                        src: result,
                        width: operation_width,
                    },
                ));
            }
        }
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn lift_sse_palignr(
        &self,
        bytes: &[u8],
        prefix: &X86Prefix,
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if !prefix.operand_size_override && prefix.rep_prefix.is_none() && !prefix.lock {
            return Err(LiftError::Unsupported {
                addr: pc,
                mnemonic: "MMX PALIGNR".to_string(),
            });
        }
        if !prefix.operand_size_override
            || prefix.rep_prefix.is_some()
            || prefix.lock
            || prefix.rex2.is_some()
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let modrm = decode_modrm(bytes, prefix, pc)?;
        if bytes.len() <= modrm.bytes_consumed {
            return Err(LiftError::Incomplete {
                addr: pc,
                have: prefix.cursor + modrm.bytes_consumed,
                need: prefix.cursor + modrm.bytes_consumed + 1,
            });
        }
        let imm = bytes[modrm.bytes_consumed];
        let next_pc = pc + prefix.cursor as u64 + modrm.bytes_consumed as u64 + 1;
        let mut ops = Vec::new();
        let low = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::X86CheckAlignment {
                    addr: addr.clone(),
                    alignment: 16,
                },
            ));
            let loaded = ctx.alloc_vreg();
            ops.push(SmirOp::with_hint(
                OpId(ops.len() as u16),
                pc,
                OpKind::VLoad {
                    dst: loaded,
                    addr,
                    width: VecWidth::V128,
                },
                X86OpHint::VecAlign(X86VecAlign::Aligned),
            ));
            loaded
        } else {
            self.xmm(modrm.rm)
        };
        let dst = self.xmm(modrm.reg);
        let raw = ctx.alloc_vreg();
        self.append_align_right(raw, dst, low, VecWidth::V128, imm, pc, ctx, &mut ops);
        self.append_legacy_packed_result(dst, raw, VecElementType::I8, pc, ctx, &mut ops);
        Ok(LiftResult::fallthrough(
            ops,
            prefix.cursor + modrm.bytes_consumed + 1,
        ))
    }

    fn lift_sse_round(
        &self,
        opcode: u8,
        bytes: &[u8],
        prefix: &X86Prefix,
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if !prefix.operand_size_override
            || prefix.rep_prefix.is_some()
            || prefix.lock
            || prefix.rex2.is_some()
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let elem = if matches!(opcode, 0x08 | 0x0A) {
            VecElementType::F32
        } else {
            VecElementType::F64
        };
        let scalar = matches!(opcode, 0x0A | 0x0B);
        let modrm = decode_modrm(bytes, prefix, pc)?;
        let imm_offset = modrm.bytes_consumed;
        if bytes.len() <= imm_offset {
            return Err(LiftError::Incomplete {
                addr: pc,
                have: prefix.cursor + imm_offset,
                need: prefix.cursor + imm_offset + 1,
            });
        }
        let imm = bytes[imm_offset];
        let next_pc = pc + prefix.cursor as u64 + imm_offset as u64 + 1;
        let mut ops = Vec::new();
        let src = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            if scalar {
                let loaded = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::Load {
                        dst: loaded,
                        addr,
                        width: if elem == VecElementType::F32 {
                            MemWidth::B4
                        } else {
                            MemWidth::B8
                        },
                        sign: SignExtend::Zero,
                    },
                ));
                loaded
            } else {
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::X86CheckAlignment {
                        addr: addr.clone(),
                        alignment: 16,
                    },
                ));
                let loaded = ctx.alloc_vreg();
                ops.push(SmirOp::with_hint(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VLoad {
                        dst: loaded,
                        addr,
                        width: VecWidth::V128,
                    },
                    X86OpHint::VecAlign(X86VecAlign::Aligned),
                ));
                loaded
            }
        } else {
            self.xmm(modrm.rm)
        };
        let mode = if imm & 4 != 0 {
            FpRoundMode::Dynamic
        } else {
            match imm & 3 {
                0 => FpRoundMode::RoundNearest,
                1 => FpRoundMode::RoundDown,
                2 => FpRoundMode::RoundUp,
                _ => FpRoundMode::RoundTowardZero,
            }
        };
        let dst = self.xmm(modrm.reg);
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::X86Round {
                dst,
                merge: dst,
                src,
                elem,
                width: VecWidth::V128,
                lanes: if scalar {
                    1
                } else {
                    VecWidth::V128.lanes(elem) as u8
                },
                scalar_source: scalar,
                zero_upper: false,
                mode,
                suppress_precision: imm & 8 != 0,
            },
        ));
        Ok(LiftResult::fallthrough(ops, prefix.cursor + imm_offset + 1))
    }

    fn lift_sse_immediate_blend(
        &self,
        opcode: u8,
        bytes: &[u8],
        prefix: &X86Prefix,
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if !prefix.operand_size_override
            || prefix.rep_prefix.is_some()
            || prefix.lock
            || prefix.rex2.is_some()
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let (elem, repeat_128) = match opcode {
            0x0C => (VecElementType::I32, false),
            0x0D => (VecElementType::I64, false),
            0x0E => (VecElementType::I16, true),
            _ => unreachable!(),
        };
        let modrm = decode_modrm(bytes, prefix, pc)?;
        let imm_offset = modrm.bytes_consumed;
        if bytes.len() <= imm_offset {
            return Err(LiftError::Incomplete {
                addr: pc,
                have: prefix.cursor + imm_offset,
                need: prefix.cursor + imm_offset + 1,
            });
        }
        let imm = bytes[imm_offset];
        let next_pc = pc + prefix.cursor as u64 + imm_offset as u64 + 1;
        let mut ops = Vec::new();
        let src2 = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::X86CheckAlignment {
                    addr: addr.clone(),
                    alignment: 16,
                },
            ));
            let loaded = ctx.alloc_vreg();
            ops.push(SmirOp::with_hint(
                OpId(ops.len() as u16),
                pc,
                OpKind::VLoad {
                    dst: loaded,
                    addr,
                    width: VecWidth::V128,
                },
                X86OpHint::VecAlign(X86VecAlign::Aligned),
            ));
            loaded
        } else {
            self.xmm(modrm.rm)
        };
        let dst = self.xmm(modrm.reg);
        let raw = ctx.alloc_vreg();
        self.append_immediate_blend(
            raw,
            dst,
            src2,
            elem,
            VecWidth::V128,
            imm,
            repeat_128,
            pc,
            ctx,
            &mut ops,
        );
        self.append_legacy_packed_result(dst, raw, elem, pc, ctx, &mut ops);
        Ok(LiftResult::fallthrough(ops, prefix.cursor + imm_offset + 1))
    }

