    fn lift_cmpccxadd(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.pp != X86SsePrefix::OpSize || prefix.width != VecWidth::V128 {
            return Err(LiftError::Unsupported {
                addr: pc,
                mnemonic: "CMPccXADD reserved vector prefix".to_string(),
            });
        }

        let (modrm_prefix, add, width, prefix_bytes) = match prefix.encoding {
            VecEncodingKind::Vex => {
                let width = if prefix.w { MemWidth::B8 } else { MemWidth::B4 };
                (
                    X86Prefix {
                        rex: prefix.rex,
                        operand_size_override: true,
                        cursor: prefix.bytes + 1,
                        ..X86Prefix::default()
                    },
                    self.gpr(prefix.vvvv),
                    width,
                    prefix.bytes,
                )
            }
            VecEncodingKind::Evex => {
                let apx = decode_apx_evex_prefix_for_map(bytes, pc, 2)?;
                if apx.pp != 1 || apx.aaa != 0 || apx.nf || apx.nd || (bytes[3] & 0xE0) != 0 {
                    return Err(LiftError::Unsupported {
                        addr: pc,
                        mnemonic: "EVEX CMPccXADD reserved field".to_string(),
                    });
                }
                let width = if apx.w { MemWidth::B8 } else { MemWidth::B4 };
                (
                    apx.as_modrm_prefix(apx.bytes + 1),
                    self.gpr(apx.vvvv_reg()),
                    width,
                    apx.bytes,
                )
            }
        };

        let modrm = decode_modrm(&bytes[prefix_bytes + 1..], &modrm_prefix, pc)?;
        if !modrm.is_memory {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }

        let next_pc = pc + prefix_bytes as u64 + 1 + modrm.bytes_consumed as u64;
        let x86_addr = modrm.addr.as_ref().unwrap();
        let (addr, mut ops) = self.x86_addr_to_smir(x86_addr, next_pc, ctx);
        let cmp = self.gpr(modrm.reg);
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::AtomicCmpXadd {
                dst_old: cmp,
                addr,
                cmp,
                add,
                cond: self.x86_cond(opcode & 0x0F),
                width,
                order: MemoryOrder::SeqCst,
            },
        ));

        Ok(LiftResult::fallthrough(
            ops,
            prefix_bytes + 1 + modrm.bytes_consumed,
        ))
    }

    fn lift_vex_integer_compare(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Vex
            || prefix.pp != X86SsePrefix::OpSize
            || !matches!(prefix.width, VecWidth::V128 | VecWidth::V256)
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let (elem, cond) = match opcode {
            0x64 => (VecElementType::I8, VecCmpCond::Gt),
            0x65 => (VecElementType::I16, VecCmpCond::Gt),
            0x66 => (VecElementType::I32, VecCmpCond::Gt),
            0x74 => (VecElementType::I8, VecCmpCond::Eq),
            0x75 => (VecElementType::I16, VecCmpCond::Eq),
            0x76 => (VecElementType::I32, VecCmpCond::Eq),
            0x29 => (VecElementType::I64, VecCmpCond::Eq),
            0x37 => (VecElementType::I64, VecCmpCond::Gt),
            _ => unreachable!(),
        };
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            operand_size_override: true,
            cursor,
            ..X86Prefix::default()
        };
        let after_opcode = &bytes[cursor..];
        let modrm = decode_modrm(after_opcode, &modrm_prefix, pc)?;
        let next_pc = pc + cursor as u64 + modrm.bytes_consumed as u64;
        let mut ops = Vec::new();
        let src2 = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            let loaded = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VLoad {
                    dst: loaded,
                    addr,
                    width: prefix.width,
                },
            ));
            loaded
        } else {
            self.vec_reg(modrm.rm, prefix.width)
        };
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::VCmp {
                dst: self.vec_reg(modrm.reg, prefix.width),
                src1: self.vec_reg(prefix.vvvv, prefix.width),
                src2,
                cond,
                elem,
                lanes: prefix.width.lanes(elem) as u8,
            },
        ));
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn lift_vex_integer_unpack(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Vex
            || prefix.pp != X86SsePrefix::OpSize
            || !matches!(prefix.width, VecWidth::V128 | VecWidth::V256)
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let elem = match opcode {
            0x60 | 0x68 => VecElementType::I8,
            0x61 | 0x69 => VecElementType::I16,
            0x62 | 0x6A => VecElementType::I32,
            0x6C | 0x6D => VecElementType::I64,
            _ => unreachable!(),
        };
        let high = matches!(opcode, 0x68 | 0x69 | 0x6A | 0x6D);
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            operand_size_override: true,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        let next_pc = pc + cursor as u64 + modrm.bytes_consumed as u64;
        let mut ops = Vec::new();
        let src2 = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            let loaded = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VLoad {
                    dst: loaded,
                    addr,
                    width: prefix.width,
                },
            ));
            loaded
        } else {
            self.vec_reg(modrm.rm, prefix.width)
        };
        self.append_unpack_shuffle(
            self.vec_reg(modrm.reg, prefix.width),
            self.vec_reg(prefix.vvvv, prefix.width),
            src2,
            elem,
            prefix.width,
            high,
            pc,
            ctx,
            &mut ops,
        );
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

    fn append_evex_vector_mask_result(
        &self,
        prefix: VecPrefix,
        dst: VReg,
        raw: VReg,
        elem: VecElementType,
        pc: u64,
        ctx: &mut LiftContext,
        ops: &mut Vec<SmirOp>,
    ) {
        self.append_evex_vector_mask_result_lanes(
            prefix,
            dst,
            raw,
            elem,
            prefix.width.lanes(elem) as u8,
            pc,
            ctx,
            ops,
        );
    }

    fn append_evex_vector_mask_result_lanes(
        &self,
        prefix: VecPrefix,
        dst: VReg,
        raw: VReg,
        elem: VecElementType,
        lanes: u8,
        pc: u64,
        ctx: &mut LiftContext,
        ops: &mut Vec<SmirOp>,
    ) {
        if prefix.aaa == 0 {
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VMov {
                    dst,
                    src: raw,
                    width: prefix.width,
                },
            ));
            return;
        }

        let mask = VReg::Arch(ArchReg::X86(X86Reg::K(prefix.aaa)));
        let old = if prefix.zeroing {
            None
        } else {
            let old = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VMov {
                    dst: old,
                    src: dst,
                    width: prefix.width,
                },
            ));
            Some(old)
        };
        let zero = ctx.alloc_vreg();
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::Mov {
                dst: zero,
                src: SrcOperand::Imm(0),
                width: OpWidth::W64,
            },
        ));
        for lane in 0..lanes {
            let shifted = ctx.alloc_vreg();
            let cond = ctx.alloc_vreg();
            let active = ctx.alloc_vreg();
            let selected = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Shr {
                    dst: shifted,
                    src: mask,
                    amount: SrcOperand::Imm(i64::from(lane)),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::And {
                    dst: cond,
                    src1: shifted,
                    src2: SrcOperand::Imm(1),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VExtractLane {
                    dst: active,
                    vec: raw,
                    lane,
                    elem,
                    sign: SignExtend::Zero,
                },
            ));
            let inactive = if let Some(old) = old {
                let inactive = ctx.alloc_vreg();
                ops.push(SmirOp::new(
                    OpId(ops.len() as u16),
                    pc,
                    OpKind::VExtractLane {
                        dst: inactive,
                        vec: old,
                        lane,
                        elem,
                        sign: SignExtend::Zero,
                    },
                ));
                inactive
            } else {
                zero
            };
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::Select {
                    dst: selected,
                    cond,
                    src_true: active,
                    src_false: inactive,
                    width: match elem {
                        VecElementType::I8 => OpWidth::W8,
                        VecElementType::I16 => OpWidth::W16,
                        VecElementType::I32 | VecElementType::F32 => OpWidth::W32,
                        VecElementType::I64 | VecElementType::F64 => OpWidth::W64,
                        _ => unreachable!(),
                    },
                },
            ));
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VInsertLane {
                    dst,
                    vec: if lane == 0 { raw } else { dst },
                    scalar: selected,
                    lane,
                    elem,
                },
            ));
        }
    }

    fn lift_vex_integer_pack(
        &self,
        prefix: VecPrefix,
        opcode: u8,
        bytes: &[u8],
        pc: u64,
        ctx: &mut LiftContext,
    ) -> Result<LiftResult, LiftError> {
        if prefix.encoding != VecEncodingKind::Vex
            || prefix.pp != X86SsePrefix::OpSize
            || !matches!(prefix.width, VecWidth::V128 | VecWidth::V256)
        {
            return Err(LiftError::InvalidEncoding {
                addr: pc,
                bytes: bytes.to_vec(),
            });
        }
        let src_elem = match opcode {
            0x63 | 0x67 => VecElementType::I16,
            0x6B | 0x2B => VecElementType::I32,
            _ => unreachable!(),
        };
        let cursor = prefix.bytes + 1;
        let modrm_prefix = X86Prefix {
            rex: prefix.rex,
            operand_size_override: true,
            cursor,
            ..X86Prefix::default()
        };
        let modrm = decode_modrm(&bytes[cursor..], &modrm_prefix, pc)?;
        let next_pc = pc + cursor as u64 + modrm.bytes_consumed as u64;
        let mut ops = Vec::new();
        let src2 = if modrm.is_memory {
            let (addr, pre_ops) = self.x86_addr_to_smir(modrm.addr.as_ref().unwrap(), next_pc, ctx);
            ops.extend(pre_ops);
            let loaded = ctx.alloc_vreg();
            ops.push(SmirOp::new(
                OpId(ops.len() as u16),
                pc,
                OpKind::VLoad {
                    dst: loaded,
                    addr,
                    width: prefix.width,
                },
            ));
            loaded
        } else {
            self.vec_reg(modrm.rm, prefix.width)
        };
        let src_lanes = prefix.width.lanes(src_elem) as u8;
        ops.push(SmirOp::new(
            OpId(ops.len() as u16),
            pc,
            OpKind::VPackSat {
                dst: self.vec_reg(modrm.reg, prefix.width),
                src1: src2,
                src2: self.vec_reg(prefix.vvvv, prefix.width),
                src_elem,
                to_unsigned: matches!(opcode, 0x67 | 0x2B),
                src_lanes,
                block_lanes: (16 / src_elem.bytes()) as u8,
            },
        ));
        Ok(LiftResult::fallthrough(ops, cursor + modrm.bytes_consumed))
    }

