    #[test]
    fn lift_nop_cache_and_prefetch_hints_consume_complete_encodings() {
        for bytes in [
            &[0x0F, 0x08][..],
            &[0x0F, 0x09][..],
            &[0x0F, 0x1A, 0xC0][..],
            &[0x0F, 0x1B, 0xC0][..],
            &[0xF3, 0x0F, 0x1E, 0xFA][..], // ENDBR64
            &[0x0F, 0x1F, 0x84, 0x88, 0x78, 0x56, 0x34, 0x12][..],
            &[0x0F, 0x18, 0x4C, 0x88, 0x20][..],
            &[0x0F, 0x0D, 0x4C, 0x88, 0x20][..],
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
            assert!(result.ops.is_empty(), "{bytes:02X?}");
            assert!(matches!(result.control_flow, ControlFlow::Fallthrough));
        }

        let cldemote = lift_single(&[0x0F, 0x1C, 0x40, 0x20]).unwrap();
        assert_eq!(cldemote.bytes_consumed, 4);
        assert!(matches!(
            cldemote.ops.as_slice(),
            [SmirOp {
                kind: OpKind::X86CacheControl {
                    addr: Address::BaseOffset {
                        base: VReg::Arch(ArchReg::X86(X86Reg::Rax)),
                        offset: 0x20,
                        ..
                    },
                    kind: X86CacheControlKind::Cldemote,
                },
                ..
            }]
        ));
        assert!(cldemote.ops[0].kind.has_side_effects());
        assert!(!cldemote.ops[0].kind.reads_memory());

        let cldemote_addr32 = lift_single(&[0x67, 0x0F, 0x1C, 0x43, 0x20]).unwrap();
        assert_eq!(cldemote_addr32.bytes_consumed, 5);
        assert!(matches!(
            cldemote_addr32.ops.last().map(|op| &op.kind),
            Some(OpKind::X86CacheControl {
                kind: X86CacheControlKind::Cldemote,
                ..
            })
        ));
        assert!(
            cldemote_addr32.ops[..cldemote_addr32.ops.len() - 1]
                .iter()
                .all(|op| matches!(
                    op.kind,
                    OpKind::Mov {
                        width: OpWidth::W32,
                        ..
                    } | OpKind::Add {
                        width: OpWidth::W32,
                        flags: FlagUpdate::None,
                        ..
                    }
                ))
        );

        for bytes in [
            &[0x0F, 0x1C, 0xC0][..],
            &[0x0F, 0x1C, 0x08][..],
            &[0x66, 0x0F, 0x1C, 0xD8][..],
            &[0xF2, 0x0F, 0x1C, 0xF8][..],
            &[0xF3, 0x0F, 0x1C, 0x08][..],
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
            assert!(result.ops.is_empty(), "reserved hint {bytes:02X?}");
        }
        assert!(matches!(
            lift_single(&[0xF0, 0x0F, 0x1C, 0x00]),
            Err(LiftError::InvalidEncoding { .. })
        ));

        let rdssp = lift_single(&[0xF3, 0x0F, 0x1E, 0xC8]).unwrap();
        assert!(matches!(
            rdssp.control_flow,
            ControlFlow::Trap {
                kind: TrapKind::InvalidOpcode
            }
        ));
    }

    #[test]
    fn lift_rdtsc_has_exact_destinations_and_length() {
        let result = lift_single(&[0x0F, 0x31]).unwrap();
        assert_eq!(result.bytes_consumed, 2);
        assert!(matches!(
            result.ops.as_slice(),
            [SmirOp {
                kind: OpKind::X86ReadTsc {
                    dst_lo: VReg::Arch(ArchReg::X86(X86Reg::Rax)),
                    dst_hi: VReg::Arch(ArchReg::X86(X86Reg::Rdx)),
                },
                ..
            }]
        ));
        assert!(result.ops[0].kind.has_side_effects());
    }

    #[test]
    fn lift_packed_sse_moves_arithmetic_and_vex_divide() {
        let movups = lift_single(&[0x0F, 0x10, 0xC1]).unwrap();
        assert!(matches!(
            movups.ops.as_slice(),
            [SmirOp {
                kind: OpKind::VMov {
                    dst: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                    src: VReg::Arch(ArchReg::X86(X86Reg::Xmm(1))),
                    width: VecWidth::V128,
                },
                x86_hint: Some(X86OpHint::SseMov { opcode: 0x10, .. }),
                ..
            }]
        ));

        for (bytes, expected_elem, expected) in [
            (&[0x0F, 0x58, 0xC1][..], VecElementType::F32, "add"),
            (&[0x66, 0x0F, 0x59, 0xC1][..], VecElementType::F64, "mul"),
            (&[0x0F, 0x5C, 0xC1][..], VecElementType::F32, "sub"),
            (&[0x66, 0x0F, 0x5E, 0xC1][..], VecElementType::F64, "div"),
        ] {
            let result = lift_single(bytes).unwrap();
            let matches_kind = result.ops.iter().any(|op| match (&op.kind, expected) {
                (OpKind::VAdd { elem, .. }, "add")
                | (OpKind::VMul { elem, .. }, "mul")
                | (OpKind::VSub { elem, .. }, "sub")
                | (OpKind::VDiv { elem, .. }, "div") => *elem == expected_elem,
                _ => false,
            });
            assert!(matches_kind, "{bytes:02X?}");
        }

        let vex_divps = lift_single(&[0xC5, 0xF8, 0x5E, 0xC1]).unwrap();
        assert!(matches!(
            vex_divps.ops.last().unwrap().kind,
            OpKind::VDiv {
                elem: VecElementType::F32,
                lanes: 4,
                ..
            }
        ));
        let vex_divpd = lift_single(&[0xC5, 0xF9, 0x5E, 0xC1]).unwrap();
        assert!(matches!(
            vex_divpd.ops.last().unwrap().kind,
            OpKind::VDiv {
                elem: VecElementType::F64,
                lanes: 2,
                ..
            }
        ));

        let xorps = lift_single(&[0x0F, 0x57, 0xC1]).unwrap();
        assert!(xorps.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VXor {
                width: VecWidth::V128,
                ..
            }
        )));
        let andnps = lift_single(&[0x0F, 0x55, 0xC1]).unwrap();
        assert!(matches!(
            andnps.ops.last().unwrap().kind,
            OpKind::VAndNot {
                width: VecWidth::V128,
                src1: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                src2: VReg::Arch(ArchReg::X86(X86Reg::Xmm(1))),
                ..
            }
        ));
        let vex_andps = lift_single(&[0xC5, 0xF8, 0x54, 0xC1]).unwrap();
        assert!(matches!(
            vex_andps.ops.last().unwrap().kind,
            OpKind::VAnd {
                width: VecWidth::V128,
                ..
            }
        ));
        let vex_andnps = lift_single(&[0xC5, 0xF8, 0x55, 0xC1]).unwrap();
        assert!(matches!(
            vex_andnps.ops.last().unwrap().kind,
            OpKind::VAndNot {
                width: VecWidth::V128,
                ..
            }
        ));
        let evex_andnps = lift_single(&[0x62, 0xF1, 0x7C, 0x48, 0x55, 0xC1]).unwrap();
        assert!(matches!(
            evex_andnps.ops.last().unwrap().kind,
            OpKind::VAndNot {
                dst: VReg::Arch(ArchReg::X86(X86Reg::Zmm(0))),
                src1: VReg::Arch(ArchReg::X86(X86Reg::Zmm(0))),
                src2: VReg::Arch(ArchReg::X86(X86Reg::Zmm(1))),
                width: VecWidth::V512,
            }
        ));

        let movss = lift_single(&[0xF3, 0x0F, 0x10, 0xC1]).unwrap();
        assert!(matches!(
            movss.ops.as_slice(),
            [
                SmirOp {
                    kind: OpKind::VExtractLane {
                        vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(1))),
                        elem: VecElementType::F32,
                        ..
                    },
                    ..
                },
                SmirOp {
                    kind: OpKind::VInsertLane {
                        dst: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                        vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                        elem: VecElementType::F32,
                        ..
                    },
                    ..
                }
            ]
        ));

        let addsd = lift_single(&[0xF2, 0x0F, 0x58, 0xC1]).unwrap();
        assert!(addsd.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VAdd {
                elem: VecElementType::F64,
                lanes: 1,
                ..
            }
        )));
        assert!(matches!(
            addsd.ops.last().unwrap().kind,
            OpKind::VInsertLane {
                dst: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(0))),
                elem: VecElementType::F64,
                ..
            }
        ));

        let movss_mem = lift_single(&[0xF3, 0x0F, 0x10, 0x00]).unwrap();
        assert!(matches!(
            movss_mem.ops.first().unwrap().kind,
            OpKind::Load {
                width: MemWidth::B4,
                ..
            }
        ));
        assert_eq!(
            movss_mem
                .ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::VInsertLane {
                        elem: VecElementType::F32,
                        ..
                    }
                ))
                .count(),
            4,
        );
        let movsd_store = lift_single(&[0xF2, 0x0F, 0x11, 0x00]).unwrap();
        assert!(matches!(
            movsd_store.ops.last().unwrap().kind,
            OpKind::Store {
                width: MemWidth::B8,
                ..
            }
        ));
        assert!(matches!(
            lift_single(&[0xF0, 0xF3, 0x0F, 0x58, 0xC1]),
            Err(LiftError::InvalidEncoding { .. })
        ));
    }

    #[test]
    fn lift_evex_packed_logic_models_masks_broadcast_high_regs_and_invalid_forms() {
        let high = lift_single(&[0x62, 0xA1, 0x7C, 0x40, 0x55, 0xD1]).unwrap();
        assert!(matches!(
            high.ops.as_slice(),
            [SmirOp {
                kind: OpKind::VAndNot {
                    dst: VReg::Arch(ArchReg::X86(X86Reg::Zmm(18))),
                    src1: VReg::Arch(ArchReg::X86(X86Reg::Zmm(16))),
                    src2: VReg::Arch(ArchReg::X86(X86Reg::Zmm(17))),
                    width: VecWidth::V512,
                },
                ..
            }]
        ));

        for (opcode, expected) in [(0x54, "and"), (0x55, "andn"), (0x56, "or"), (0x57, "xor")] {
            let result = lift_single(&[0x62, 0xF1, 0x7C, 0xC9, opcode, 0xD1]).unwrap();
            assert!(result.ops.iter().any(|op| match (&op.kind, expected) {
                (OpKind::VAnd { width, .. }, "and")
                | (OpKind::VAndNot { width, .. }, "andn")
                | (OpKind::VOr { width, .. }, "or")
                | (OpKind::VXor { width, .. }, "xor") => *width == VecWidth::V512,
                _ => false,
            }));
            assert_eq!(
                result
                    .ops
                    .iter()
                    .filter(|op| matches!(
                        op.kind,
                        OpKind::Select {
                            width: OpWidth::W32,
                            ..
                        }
                    ))
                    .count(),
                16,
                "opcode {opcode:02X}: one mask select per dword lane",
            );
            assert!(result.ops.iter().any(|op| matches!(
                op.kind,
                OpKind::VInsertLane {
                    dst: VReg::Arch(ArchReg::X86(X86Reg::Zmm(2))),
                    elem: VecElementType::F32,
                    lane: 15,
                    ..
                }
            )));
        }
        let pd = lift_single(&[0x62, 0xF1, 0xFD, 0x49, 0x55, 0xD1]).unwrap();
        assert_eq!(
            pd.ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::Select {
                        width: OpWidth::W64,
                        ..
                    }
                ))
                .count(),
            8,
        );
        assert!(pd.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VInsertLane {
                elem: VecElementType::F64,
                lane: 7,
                ..
            }
        )));

        let masked_memory = lift_single(&[0x62, 0xF1, 0x7C, 0x49, 0x55, 0x50, 0x02]).unwrap();
        assert_eq!(
            masked_memory
                .ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::PredLoad {
                        width: MemWidth::B4,
                        ..
                    }
                ))
                .count(),
            16,
        );
        assert!(masked_memory.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::Lea {
                addr: Address::BaseOffset {
                    offset: 128,
                    disp_size: DispSize::Disp8,
                    ..
                },
                ..
            }
        )));

        let broadcast = lift_single(&[0x62, 0xF1, 0x7C, 0x59, 0x55, 0x50, 0x08]).unwrap();
        assert_eq!(
            broadcast
                .ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::PredLoad {
                        width: MemWidth::B4,
                        ..
                    }
                ))
                .count(),
            1,
        );
        assert!(broadcast.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::PredLoad {
                addr: Address::BaseOffset {
                    offset: 32,
                    disp_size: DispSize::Disp8,
                    ..
                },
                ..
            }
        )));
        assert!(broadcast.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VBroadcast {
                elem: VecElementType::F32,
                lanes: 16,
                ..
            }
        )));

        for bytes in [
            &[0x62, 0xF1, 0xFC, 0x48, 0x55, 0xC1][..], // VANDNPS requires W0
            &[0x62, 0xF1, 0x7D, 0x48, 0x55, 0xC1][..], // VANDNPD requires W1
            &[0x62, 0xF1, 0x7C, 0xC8, 0x55, 0xC1][..], // {z} requires a mask
            &[0x62, 0xF1, 0x7C, 0x58, 0x55, 0xC1][..], // EVEX.b reserved for reg
            &[0x62, 0xF1, 0x7C, 0x58, 0x57, 0x00][..], // VXORPS has no broadcast
            &[0x62, 0xF1, 0x7C, 0x68, 0x55, 0xC1][..], // LL=3 is reserved
            &[0x62, 0xF1, 0x7E, 0x48, 0x55, 0xC1][..], // F3 form is undefined
        ] {
            assert!(
                matches!(
                    lift_single(bytes),
                    Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
                ),
                "invalid EVEX packed logic accepted: {bytes:02X?}",
            );
        }
    }

    #[test]
    fn lift_legacy_and_vex_movmsk_extracts_exact_lanes_and_rejects_reserved_forms() {
        for (bytes, dst, src, elem, lanes, width) in [
            (
                &[0x0F, 0x50, 0xC1][..],
                X86Reg::Rax,
                X86Reg::Xmm(1),
                VecElementType::F32,
                4usize,
                OpWidth::W32,
            ),
            (
                &[0x66, 0x0F, 0x50, 0xD1][..],
                X86Reg::Rdx,
                X86Reg::Xmm(1),
                VecElementType::F64,
                2,
                OpWidth::W32,
            ),
            (
                &[0x66, 0x48, 0x0F, 0x50, 0xC1][..],
                X86Reg::Rax,
                X86Reg::Xmm(1),
                VecElementType::F64,
                2,
                OpWidth::W64,
            ),
            (
                &[0x45, 0x0F, 0x50, 0xC1][..],
                X86Reg::R8,
                X86Reg::Xmm(9),
                VecElementType::F32,
                4,
                OpWidth::W32,
            ),
            (
                &[0xC5, 0xF8, 0x50, 0xC1][..],
                X86Reg::Rax,
                X86Reg::Xmm(1),
                VecElementType::F32,
                4,
                OpWidth::W32,
            ),
            (
                &[0xC5, 0xFD, 0x50, 0xD1][..],
                X86Reg::Rdx,
                X86Reg::Ymm(1),
                VecElementType::F64,
                4,
                OpWidth::W32,
            ),
            (
                &[0xC4, 0x41, 0x7C, 0x50, 0xC1][..],
                X86Reg::R8,
                X86Reg::Ymm(9),
                VecElementType::F32,
                8,
                OpWidth::W32,
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
            let extracts = result
                .ops
                .iter()
                .filter_map(|op| match op.kind {
                    OpKind::VExtractLane {
                        vec: VReg::Arch(ArchReg::X86(actual_src)),
                        lane,
                        elem: actual_elem,
                        sign: SignExtend::Zero,
                        ..
                    } if actual_src == src && actual_elem == elem => Some(lane),
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(
                extracts,
                (0..lanes as u8).collect::<Vec<_>>(),
                "{bytes:02X?}"
            );
            assert!(matches!(
                result.ops.last().unwrap().kind,
                OpKind::Mov {
                    dst: VReg::Arch(ArchReg::X86(actual_dst)),
                    width: actual_width,
                    ..
                } if actual_dst == dst && actual_width == width
            ));
            assert!(
                result
                    .ops
                    .iter()
                    .all(|op| op.kind.flags_written().is_empty())
            );
        }

        for bytes in [
            &[0x0F, 0x50, 0x01][..],                   // memory source is undefined
            &[0xF3, 0x0F, 0x50, 0xC1][..],             // no F3 legacy form
            &[0xF0, 0x0F, 0x50, 0xC1][..],             // LOCK is undefined
            &[0xC5, 0xF0, 0x50, 0xC1][..],             // VEX.vvvv != 1111b
            &[0xC5, 0xFA, 0x50, 0xC1][..],             // no F3 VEX form
            &[0xC5, 0xF8, 0x50, 0x01][..],             // VEX memory source
            &[0x62, 0xF1, 0x7C, 0x08, 0x50, 0xC1][..], // no EVEX form
        ] {
            assert!(
                matches!(
                    lift_single(bytes),
                    Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
                ),
                "invalid MOVMSK accepted: {bytes:02X?}",
            );
        }
    }

    #[test]
    fn lift_legacy_and_vex_pmovmskb_extracts_all_bytes_and_rejects_reserved_forms() {
        for (bytes, dst, src, lanes) in [
            (
                &[0x66, 0x0F, 0xD7, 0xC1][..],
                X86Reg::Rax,
                X86Reg::Xmm(1),
                16usize,
            ),
            (
                &[0x66, 0x45, 0x0F, 0xD7, 0xC1][..],
                X86Reg::R8,
                X86Reg::Xmm(9),
                16,
            ),
            (
                &[0xC5, 0xF9, 0xD7, 0xC1][..],
                X86Reg::Rax,
                X86Reg::Xmm(1),
                16,
            ),
            (
                &[0xC5, 0xFD, 0xD7, 0xC2][..],
                X86Reg::Rax,
                X86Reg::Ymm(2),
                32,
            ),
            (
                &[0xC4, 0x41, 0xFD, 0xD7, 0xCA][..],
                X86Reg::R9,
                X86Reg::Ymm(10),
                32,
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
            let extracts = result
                .ops
                .iter()
                .filter_map(|op| match op.kind {
                    OpKind::VExtractLane {
                        vec: VReg::Arch(ArchReg::X86(actual_src)),
                        lane,
                        elem: VecElementType::I8,
                        sign: SignExtend::Zero,
                        ..
                    } if actual_src == src => Some(lane),
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(extracts, (0..lanes as u8).collect::<Vec<_>>());
            assert!(matches!(
                result.ops.last().unwrap().kind,
                OpKind::Mov {
                    dst: VReg::Arch(ArchReg::X86(actual_dst)),
                    width: OpWidth::W32,
                    ..
                } if actual_dst == dst
            ));
            assert!(
                result
                    .ops
                    .iter()
                    .all(|op| op.kind.flags_written().is_empty())
            );
        }

        for bytes in [
            &[0x66, 0x0F, 0xD7, 0x01][..],
            &[0xF3, 0x66, 0x0F, 0xD7, 0xC1][..],
            &[0xC5, 0xED, 0xD7, 0xC1][..],
            &[0xC5, 0xFC, 0xD7, 0xC1][..],
            &[0xC5, 0xFD, 0xD7, 0x01][..],
            &[0x62, 0xF1, 0x7D, 0x08, 0xD7, 0xC1][..],
        ] {
            assert!(
                matches!(
                    lift_single(bytes),
                    Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
                ),
                "invalid PMOVMSKB accepted: {bytes:02X?}",
            );
        }
        assert!(matches!(
            lift_single(&[0x0F, 0xD7, 0xC1]),
            Err(LiftError::Unsupported { mnemonic, .. }) if mnemonic == "MMX PMOVMSKB"
        ));
    }

    #[test]
    fn lift_maskmovdqu_covers_registers_implicit_addresses_and_reserved_forms() {
        for (bytes, data, mask) in [
            (
                &[0x66, 0x45, 0x0F, 0xF7, 0xC1][..],
                X86Reg::Xmm(8),
                X86Reg::Xmm(9),
            ),
            (
                &[0xC4, 0x41, 0x79, 0xF7, 0xC1][..],
                X86Reg::Xmm(8),
                X86Reg::Xmm(9),
            ),
            (
                &[0xC4, 0xE1, 0xF9, 0xF7, 0xC1][..],
                X86Reg::Xmm(0),
                X86Reg::Xmm(1),
            ),
            (
                &[0x66, 0x0F, 0xF7, 0xC0][..],
                X86Reg::Xmm(0),
                X86Reg::Xmm(0),
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
            assert_eq!(
                result
                    .ops
                    .iter()
                    .filter(|op| matches!(
                        op.kind,
                        OpKind::PredStore {
                            width: MemWidth::B1,
                            ..
                        }
                    ))
                    .count(),
                16,
            );
            for lane in 0..16u8 {
                assert!(result.ops.iter().any(|op| matches!(
                    op.kind,
                    OpKind::VExtractLane {
                        vec: VReg::Arch(ArchReg::X86(actual)),
                        lane: actual_lane,
                        elem: VecElementType::I8,
                        ..
                    } if actual == data && actual_lane == lane
                )));
                assert!(result.ops.iter().any(|op| matches!(
                    op.kind,
                    OpKind::VExtractLane {
                        vec: VReg::Arch(ArchReg::X86(actual)),
                        lane: actual_lane,
                        elem: VecElementType::I8,
                        ..
                    } if actual == mask && actual_lane == lane
                )));
                assert!(result.ops.iter().any(|op| matches!(
                    op.kind,
                    OpKind::PredStore {
                        addr: Address::BaseOffset {
                            base: VReg::Arch(ArchReg::X86(X86Reg::Rdi)),
                            offset,
                            ..
                        },
                        ..
                    } if offset == i64::from(lane)
                )));
            }
            assert!(result.ops.iter().all(|op| {
                op.kind.flags_written().is_empty()
                    && !op.kind.dests().iter().any(|dst| {
                        matches!(
                            dst,
                            VReg::Arch(ArchReg::X86(
                                X86Reg::Xmm(_) | X86Reg::Ymm(_) | X86Reg::Zmm(_)
                            ))
                        )
                    })
            }));
        }

        let addr32 = lift_single(&[0x67, 0xC4, 0x41, 0x79, 0xF7, 0xC1]).unwrap();
        assert_eq!(addr32.bytes_consumed, 6);
        let truncated = addr32
            .ops
            .iter()
            .find_map(|op| match op.kind {
                OpKind::And {
                    dst,
                    src1: VReg::Arch(ArchReg::X86(X86Reg::Rdi)),
                    src2: SrcOperand::Imm(0xFFFF_FFFF),
                    width: OpWidth::W64,
                    flags: FlagUpdate::None,
                } => Some(dst),
                _ => None,
            })
            .expect("67h must zero-extend EDI");
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::PredStore {
                addr: Address::BaseOffset {
                    base,
                    offset: 15,
                    ..
                },
                ..
            } if base == truncated
        )));

        let fs = lift_single(&[0x64, 0xC5, 0xF9, 0xF7, 0xC1]).unwrap();
        assert!(fs.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::PredStore {
                addr: Address::SegmentRel {
                    segment: VReg::Arch(ArchReg::X86(X86Reg::FsBase)),
                    base: Some(VReg::Arch(ArchReg::X86(X86Reg::Rdi))),
                    disp: 15,
                    ..
                },
                ..
            }
        )));

        for bytes in [
            &[0x66, 0x0F, 0xF7, 0x01][..],             // ModRM.mod must be 3
            &[0xF3, 0x66, 0x0F, 0xF7, 0xC1][..],       // no REP legacy form
            &[0xF0, 0x66, 0x0F, 0xF7, 0xC1][..],       // LOCK is invalid
            &[0xC5, 0xFD, 0xF7, 0xC1][..],             // VEX.L=1
            &[0xC5, 0xE9, 0xF7, 0xC1][..],             // VEX.vvvv is reserved
            &[0xC5, 0xF8, 0xF7, 0xC1][..],             // mandatory 66 absent
            &[0xC5, 0xF9, 0xF7, 0x01][..],             // ModRM.mod must be 3
            &[0x40, 0xC5, 0xF9, 0xF7, 0xC1][..],       // REX before VEX
            &[0x66, 0xC5, 0xF9, 0xF7, 0xC1][..],       // encoded SIMD prefix before VEX
            &[0x62, 0xF1, 0x7D, 0x08, 0xF7, 0xC1][..], // no EVEX form
        ] {
            assert!(
                matches!(
                    lift_single(bytes),
                    Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
                ),
                "invalid MASKMOVDQU accepted: {bytes:02X?}",
            );
        }
        assert!(matches!(
            lift_single(&[0x0F, 0xF7, 0xC1]),
            Err(LiftError::Unsupported { mnemonic, .. }) if mnemonic == "MMX MASKMOVQ"
        ));
    }

    #[test]
    fn lift_vex_masked_memory_covers_float_integer_load_store_and_fault_lanes() {
        for (bytes, elem, lanes, load) in [
            (
                &[0xC4, 0xE2, 0x71, 0x2C, 0x17][..],
                VecElementType::F32,
                4usize,
                true,
            ),
            (
                &[0xC4, 0xE2, 0x75, 0x2F, 0x17][..],
                VecElementType::F64,
                4,
                false,
            ),
            (
                &[0xC4, 0xE2, 0x71, 0x8C, 0x17][..],
                VecElementType::I32,
                4,
                true,
            ),
            (
                &[0xC4, 0xE2, 0xF1, 0x8E, 0x17][..],
                VecElementType::I64,
                2,
                false,
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len());
            assert_eq!(
                result
                    .ops
                    .iter()
                    .filter(|op| matches!(
                        op.kind,
                        OpKind::VExtractLane {
                            vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(1) | X86Reg::Ymm(1))),
                            elem: actual,
                            ..
                        } if actual == elem
                    ))
                    .count(),
                lanes,
            );
            assert_eq!(
                result
                    .ops
                    .iter()
                    .filter(|op| if load {
                        matches!(op.kind, OpKind::PredLoad { .. })
                    } else {
                        matches!(op.kind, OpKind::PredStore { .. })
                    })
                    .count(),
                lanes,
            );
            assert!(
                result
                    .ops
                    .iter()
                    .all(|op| op.kind.flags_written().is_empty())
            );
        }

        let addr32 = lift_single(&[0x67, 0xC4, 0xE2, 0x71, 0x2C, 0x14, 0x77]).unwrap();
        assert_eq!(addr32.bytes_consumed, 7);
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::Add {
                width: OpWidth::W32,
                flags: FlagUpdate::None,
                ..
            }
        )));

        for bytes in [
            &[0xC4, 0xE2, 0x71, 0x2C, 0xD2][..], // memory operand required
            &[0xC4, 0xE2, 0xF1, 0x2C, 0x17][..], // VMASKMOVPS W=1
            &[0xC4, 0xE2, 0x70, 0x2C, 0x17][..], // mandatory 66 absent
            &[0x62, 0xF2, 0x75, 0x08, 0x8C, 0x17][..], // no EVEX form
        ] {
            assert!(matches!(
                lift_single(bytes),
                Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
            ));
        }
    }

    #[test]
    fn lift_vex_fma3_covers_orders_signs_scalars_alternation_and_addresses() {
        for order in [0x90u8, 0xA0, 0xB0] {
            for low in [0x06u8, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F] {
                let scalar = matches!(low, 0x09 | 0x0B | 0x0D | 0x0F);
                let vex = if scalar { 0x71 } else { 0x75 };
                let bytes = [0xC4, 0xE2, vex, order | low, 0xD3];
                let result = lift_single(&bytes).unwrap();
                assert_eq!(result.bytes_consumed, bytes.len(), "{bytes:02X?}");
                assert!(
                    result
                        .ops
                        .iter()
                        .any(|op| matches!(op.kind, OpKind::VFma { .. }))
                );
                assert!(
                    result
                        .ops
                        .iter()
                        .all(|op| op.kind.flags_written().is_empty())
                );
            }
        }

        for (opcode, src1, src2, acc) in [
            (0x98, X86Reg::Ymm(2), X86Reg::Ymm(3), X86Reg::Ymm(1)),
            (0xA8, X86Reg::Ymm(1), X86Reg::Ymm(2), X86Reg::Ymm(3)),
            (0xB8, X86Reg::Ymm(1), X86Reg::Ymm(3), X86Reg::Ymm(2)),
        ] {
            let result = lift_single(&[0xC4, 0xE2, 0x75, opcode, 0xD3]).unwrap();
            assert!(result.ops.iter().any(|op| matches!(
                op.kind,
                OpKind::VFma {
                    src1: VReg::Arch(ArchReg::X86(actual1)),
                    src2: VReg::Arch(ArchReg::X86(actual2)),
                    acc: VReg::Arch(ArchReg::X86(actual_acc)),
                    elem: VecElementType::F32,
                    lanes: 8,
                    negate_product: false,
                    negate_acc: false,
                    ..
                } if actual1 == src1 && actual2 == src2 && actual_acc == acc
            )));
        }

        for (opcode, negate_product, negate_acc) in
            [(0x9A, false, true), (0x9C, true, false), (0x9E, true, true)]
        {
            let result = lift_single(&[0xC4, 0xE2, 0xF5, opcode, 0xD3]).unwrap();
            assert!(result.ops.iter().any(|op| matches!(
                op.kind,
                OpKind::VFma {
                    elem: VecElementType::F64,
                    negate_product: actual_product,
                    negate_acc: actual_acc,
                    ..
                } if actual_product == negate_product && actual_acc == negate_acc
            )));
        }

        let scalar = lift_single(&[0xC4, 0xE2, 0xF1, 0xB9, 0xD3]).unwrap();
        assert!(scalar.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VFma {
                elem: VecElementType::F64,
                lanes: 1,
                ..
            }
        )));
        assert!(scalar.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VExtractLane {
                vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(2))),
                lane: 1,
                elem: VecElementType::F64,
                ..
            }
        )));

        let alternating = lift_single(&[0xC4, 0xE2, 0x75, 0x96, 0xD3]).unwrap();
        assert_eq!(
            alternating
                .ops
                .iter()
                .filter(|op| matches!(op.kind, OpKind::VFma { .. }))
                .count(),
            2
        );

        let addr32 = lift_single(&[0x67, 0xC4, 0xE2, 0x75, 0x98, 0x54, 0x77, 0x20]).unwrap();
        assert_eq!(addr32.bytes_consumed, 8);
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VLoad {
                width: VecWidth::V256,
                ..
            }
        )));
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::Add {
                width: OpWidth::W32,
                flags: FlagUpdate::None,
                ..
            }
        )));

        assert!(matches!(
            lift_single(&[0xC4, 0xE2, 0x74, 0x98, 0xD3]),
            Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
        ));
        assert!(lift_single(&[0xC4, 0xE2, 0x75, 0x99, 0xD3]).is_ok()); // VEX.LIG

        let high_masked = lift_single(&[0x62, 0xA2, 0x75, 0x43, 0x98, 0xC2]).unwrap();
        assert!(high_masked.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VFma {
                src1: VReg::Arch(ArchReg::X86(X86Reg::Zmm(16))),
                src2: VReg::Arch(ArchReg::X86(X86Reg::Zmm(18))),
                acc: VReg::Arch(ArchReg::X86(X86Reg::Zmm(17))),
                lanes: 16,
                ..
            }
        )));
        assert_eq!(
            high_masked
                .ops
                .iter()
                .filter(|op| matches!(op.kind, OpKind::Select { .. }))
                .count(),
            16
        );

        let masked_memory = lift_single(&[0x62, 0xE2, 0xF5, 0xA3, 0xBE, 0x40, 0x02]).unwrap();
        assert_eq!(
            masked_memory
                .ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::PredLoad {
                        width: MemWidth::B8,
                        ..
                    }
                ))
                .count(),
            4
        );
        let broadcast = lift_single(&[0x62, 0xF2, 0x65, 0xD9, 0xA6, 0x10]).unwrap();
        assert_eq!(
            broadcast
                .ops
                .iter()
                .filter(|op| matches!(
                    op.kind,
                    OpKind::PredLoad {
                        width: MemWidth::B4,
                        ..
                    }
                ))
                .count(),
            16
        );
        let scalar_masked = lift_single(&[0x62, 0xE2, 0x55, 0x82, 0xB9, 0x20]).unwrap();
        assert!(scalar_masked.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::PredLoad {
                width: MemWidth::B4,
                ..
            }
        )));
        assert!(scalar_masked.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::VExtractLane {
                vec: VReg::Arch(ArchReg::X86(X86Reg::Xmm(20))),
                lane: 3,
                elem: VecElementType::F32,
                ..
            }
        )));
        assert!(lift_single(&[0x62, 0xA2, 0xD5, 0x12, 0xB9, 0xE6]).is_ok());

        for bytes in [
            &[0x62, 0xF2, 0x75, 0x88, 0x98, 0xC2][..],
            &[0x62, 0xF2, 0x75, 0x38, 0x98, 0xC2][..],
            &[0x62, 0xF2, 0x75, 0x60, 0x98, 0xC2][..],
        ] {
            assert!(matches!(
                lift_single(bytes),
                Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
            ));
        }
    }

    #[test]
    fn lift_sse3_addsub_horizontal_covers_legacy_vex_widths_addresses_and_invalids() {
        for (bytes, elem, width, dst) in [
            (
                &[0xF2, 0x0F, 0xD0, 0xC1][..],
                VecElementType::F32,
                VecWidth::V128,
                X86Reg::Xmm(0),
            ),
            (
                &[0x66, 0x0F, 0x7C, 0xC1][..],
                VecElementType::F64,
                VecWidth::V128,
                X86Reg::Xmm(0),
            ),
            (
                &[0xC5, 0xEB, 0x7D, 0xCB][..],
                VecElementType::F32,
                VecWidth::V128,
                X86Reg::Xmm(1),
            ),
            (
                &[0xC4, 0x41, 0x75, 0x7C, 0xCA][..],
                VecElementType::F64,
                VecWidth::V256,
                X86Reg::Ymm(9),
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len());
            assert!(result.ops.iter().any(|op| matches!(
                op.kind,
                OpKind::VInsertLane { elem: actual, .. } if actual == elem
            )));
            assert!(
                result.ops.iter().any(|op| matches!(
                    op.kind,
                    OpKind::VMov {
                        dst: VReg::Arch(ArchReg::X86(actual)),
                        width: actual_width,
                        ..
                    } if actual == dst && actual_width == width
                )) || width == VecWidth::V128 && bytes[0] != 0xC5
            );
            assert!(
                result
                    .ops
                    .iter()
                    .all(|op| op.kind.flags_written().is_empty())
            );
        }

        let legacy_mem = lift_single(&[0x66, 0x0F, 0x7D, 0x00]).unwrap();
        assert!(
            legacy_mem
                .ops
                .iter()
                .any(|op| matches!(op.kind, OpKind::X86CheckAlignment { alignment: 16, .. }))
        );
        let addr32 = lift_single(&[0x67, 0xC5, 0xFF, 0x7C, 0x54, 0x77, 0x20]).unwrap();
        assert_eq!(addr32.bytes_consumed, 7);
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::Add {
                width: OpWidth::W32,
                flags: FlagUpdate::None,
                ..
            }
        )));
        assert!(
            !addr32
                .ops
                .iter()
                .any(|op| matches!(op.kind, OpKind::X86CheckAlignment { .. }))
        );

        for bytes in [
            &[0x0F, 0x7C, 0xC1][..],
            &[0xF0, 0xF2, 0x0F, 0xD0, 0xC1][..],
            &[0xC5, 0xFC, 0x7C, 0xC1][..],
            &[0x62, 0xF1, 0x7D, 0x08, 0x7C, 0xC1][..],
        ] {
            assert!(matches!(
                lift_single(bytes),
                Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
            ));
        }
    }

    #[test]
    fn lift_reciprocal_estimates_covers_legacy_vex_scalar_packed_and_special_encodings() {
        for (bytes, op, lanes, dst) in [
            (
                &[0x0F, 0x53, 0xC1][..],
                VecUnaryOp::FRecipEstimate,
                4u8,
                X86Reg::Xmm(0),
            ),
            (
                &[0xF3, 0x45, 0x0F, 0x52, 0xC1][..],
                VecUnaryOp::FRsqrtEstimate,
                1,
                X86Reg::Xmm(8),
            ),
            (
                &[0xC5, 0xF8, 0x53, 0xD1][..],
                VecUnaryOp::FRecipEstimate,
                4,
                X86Reg::Xmm(2),
            ),
            (
                &[0xC5, 0xFC, 0x52, 0xE1][..],
                VecUnaryOp::FRsqrtEstimate,
                8,
                X86Reg::Ymm(4),
            ),
        ] {
            let result = lift_single(bytes).unwrap();
            assert_eq!(result.bytes_consumed, bytes.len());
            assert!(result.ops.iter().any(|operation| matches!(
                operation.kind,
                OpKind::VUnary {
                    op: actual,
                    lanes: actual_lanes,
                    ..
                } if actual == op && actual_lanes == lanes
            )));
            assert!(result.ops.iter().any(|operation| {
                operation
                    .kind
                    .dests()
                    .contains(&VReg::Arch(ArchReg::X86(dst)))
            }));
        }

        let legacy_packed_mem = lift_single(&[0x0F, 0x53, 0x00]).unwrap();
        assert!(
            legacy_packed_mem
                .ops
                .iter()
                .any(|op| matches!(op.kind, OpKind::X86CheckAlignment { alignment: 16, .. }))
        );
        let legacy_scalar_mem = lift_single(&[0xF3, 0x0F, 0x53, 0x00]).unwrap();
        assert!(
            !legacy_scalar_mem
                .ops
                .iter()
                .any(|op| matches!(op.kind, OpKind::X86CheckAlignment { .. }))
        );
        let addr32 = lift_single(&[0x67, 0xC5, 0xF8, 0x52, 0x54, 0x77, 0x10]).unwrap();
        assert_eq!(addr32.bytes_consumed, 7);
        assert!(addr32.ops.iter().any(|op| matches!(
            op.kind,
            OpKind::Add {
                width: OpWidth::W32,
                flags: FlagUpdate::None,
                ..
            }
        )));
        assert!(lift_single(&[0xC5, 0xFE, 0x53, 0xD1]).is_ok()); // scalar VEX.LIG

        for bytes in [
            &[0x66, 0x0F, 0x53, 0xC1][..],
            &[0xF0, 0x0F, 0x52, 0xC1][..],
            &[0xC5, 0xE8, 0x53, 0xC1][..],
            &[0xC5, 0xF9, 0x52, 0xC1][..],
            &[0x62, 0xF1, 0x7C, 0x08, 0x53, 0xC1][..],
        ] {
            assert!(matches!(
                lift_single(bytes),
                Err(LiftError::InvalidEncoding { .. } | LiftError::Unsupported { .. })
            ));
        }
    }

